class JsonReader:
    def __init__(self, path: Path):
        self.path = path

    def read(self) -> Any:
        return json.loads(self.path.read_text(encoding="utf-8"))

    def read_lines(self) -> Iterator[Dict[str, Any]]:
        for line in self.path.read_text(encoding="utf-8").splitlines():
            line = line.strip()
            if line:
                yield json.loads(line)

